1	import React, { useMemo } from 'react';
2	import { useSelector, useDispatch } from 'react-redux';
3	import {
4	  IconNetwork
5	} from '@tabler/icons';
6	import {
7	  setSelectedRequest
8	} from 'providers/ReduxStore/slices/logs';
9	import StyledWrapper from './StyledWrapper';
10	
11	const MethodBadge = ({ method }) => {
12	  const methodLower = method?.toLowerCase() || 'get';
13	
14	  return (
15	    <span className={`method-badge ${methodLower}`}>
16	      {method?.toUpperCase() || 'GET'}
17	    </span>
18	  );
19	};
20	
21	const StatusBadge = ({ status, statusCode }) => {
22	  const displayStatus = statusCode || status;
23	
24	  return (
25	    <span className="status-badge">
26	      {displayStatus}
27	    </span>
28	  );
29	};
30	
31	const RequestRow = ({ request, isSelected, onClick }) => {
32	  const { data } = request;
33	  const { request: req, response: res, timestamp } = data;
34	
35	  const formatTime = (timestamp) => {
36	    const date = new Date(timestamp);
37	    return date.toLocaleTimeString('en-US', {
38	      hour12: false,
39	      hour: '2-digit',
40	      minute: '2-digit',
41	      second: '2-digit',
42	      fractionalSecondDigits: 3
43	    });
44	  };
45	
46	  const formatDuration = (duration) => {
47	    if (!duration) return '-';
48	    if (duration < 1000) return `${Math.round(duration)}ms`;
49	    return `${(duration / 1000).toFixed(2)}s`;
50	  };
51	
52	  const formatSize = (size) => {
53	    if (!size) return '-';
54	    if (size < 1024) return `${size}B`;
55	    if (size < 1024 * 1024) return `${(size / 1024).toFixed(1)}KB`;
56	    return `${(size / (1024 * 1024)).toFixed(1)}MB`;
57	  };
58	
59	  const getUrl = () => {
60	    return req?.url || 'Unknown URL';
61	  };
62	
63	  const getDomain = () => {
64	    try {
65	      const url = new URL(getUrl());
66	      return url.hostname;
67	    } catch {
68	      return getUrl();
69	    }
70	  };
71	
72	  const getPath = () => {
73	    try {
74	      const url = new URL(getUrl());
75	      return url.pathname + url.search;
76	    } catch {
77	      return getUrl();
78	    }
79	  };
80	
81	  return (
82	    <div
83	      className={`request-row ${isSelected ? 'selected' : ''}`}
84	      onClick={onClick}
85	    >
86	      <div className="request-method">
87	        <MethodBadge method={req?.method} />
88	      </div>
89	
90	      <div className="request-status">
91	        <StatusBadge status={res?.status} statusCode={res?.statusCode} />
92	      </div>
93	
94	      <div className="request-domain" title={getDomain()}>
95	        {getDomain()}
96	      </div>
97	
98	      <div className="request-path" title={getPath()}>
99	        {getPath()}
100	      </div>
101	
102	      <div className="request-time">
103	        {formatTime(timestamp)}
104	      </div>
105	
106	      <div className="request-duration">
107	        {formatDuration(res?.duration)}
108	      </div>
109	
110	      <div className="request-size">
111	        {formatSize(res?.size)}
112	      </div>
113	    </div>
114	  );
115	};
116	
117	const NetworkTab = () => {
118	  const dispatch = useDispatch();
119	  const { networkFilters, selectedRequest } = useSelector((state) => state.logs);
120	  const collections = useSelector((state) => state.collections.collections);
121	
122	  const allRequests = useMemo(() => {
123	    const requests = [];
124	
125	    collections.forEach((collection) => {
126	      if (collection.timeline) {
127	        collection.timeline
128	          .filter((entry) => entry.type === 'request')
129	          .forEach((entry) => {
130	            requests.push({
131	              ...entry,
132	              collectionName: collection.name,
133	              collectionUid: collection.uid
134	            });
135	          });
136	      }
137	    });
138	
139	    return requests.sort((a, b) => a.timestamp - b.timestamp);
140	  }, [collections]);
141	
142	  const filteredRequests = useMemo(() => {
143	    return allRequests.filter((request) => {
144	      const method = request.data?.request?.method?.toUpperCase() || 'GET';
145	      return networkFilters[method];
146	    });
147	  }, [allRequests, networkFilters]);
148	
149	  const handleRequestClick = (request) => {
150	    dispatch(setSelectedRequest(request));
151	  };
152	
153	  return (
154	    <StyledWrapper>
155	      <div className="network-content">
156	        {filteredRequests.length === 0 ? (
157	          <div className="network-empty">
158	            <IconNetwork size={48} strokeWidth={1} />
159	            <p>No network requests</p>
160	            <span>Requests will appear here as you make API calls</span>
161	          </div>
162	        ) : (
163	          <div className="requests-container">
164	            <div className="requests-header">
165	              <div>Method</div>
166	              <div>Status</div>
167	              <div>Domain</div>
168	              <div>Path</div>
169	              <div>Time</div>
170	              <div className="text-right">Duration</div>
171	              <div className="text-right">Size</div>
172	            </div>
173	
174	            <div className="requests-list">
175	              {filteredRequests.map((request, index) => (
176	                <RequestRow
177	                  key={`${request.collectionUid}-${request.itemUid}-${request.timestamp}-${index}`}
178	                  request={request}
179	                  isSelected={selectedRequest?.timestamp === request.timestamp && selectedRequest?.itemUid === request.itemUid}
180	                  onClick={() => handleRequestClick(request)}
181	                />
182	              ))}
183	            </div>
184	          </div>
185	        )}
186	      </div>
187	    </StyledWrapper>
188	  );
189	};
190	
191	export default NetworkTab;
192

